=== FILE: uart_tx_root_cause_repro.v ===
`timescale 1ns / 1ps
// Root-cause repro for prj-a0b3e1ca75:root-cause.
// Self-checking test of the specified behaviour of uart_tx:
//   8N1 framing, one start bit (0), eight data bits LSB first, one stop bit (1),
//   CLKS_PER_BIT clock cycles per bit, and a start pulse while a frame is in
//   flight is ignored.
// Every expected value below comes from that specification, not from the
// output of any implementation. The test sends 8'hA5 and, during data bit 2,
// pulses start with 8'h3C. A correct transmitter still sends 8'hA5 and starts
// no second frame.
module uart_tx_root_cause_tb;
    localparam integer CPB           = 4;
    localparam [7:0]   FRAME_BYTE    = 8'hA5;
    localparam [7:0]   INTRUDER_BYTE = 8'h3C;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire       tx;
    wire       busy;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk  (clk),
        .rst  (rst),
        .start(start),
        .data (data),
        .tx   (tx),
        .busy (busy)
    );

    always #5 clk = ~clk;

    reg [8*128-1:0] nonce;
    integer passed   = 0;
    integer failed   = 0;
    reg     reported = 1'b0;

    reg [7:0] rx;
    reg       start_ok;
    reg       stop_ok;
    reg       idle_ok;
    integer   i;

    task check;
        input            ok;
        input [8*48-1:0] name;
        begin
            if (ok)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAILED: %0s", name);
            end
        end
    endtask

    task report;
        begin
            if (!reported) begin
                reported = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    // Watchdog: a hung frame still yields exactly one verdict line.
    initial begin
        #5000;
        if (!reported) begin
            check(1'b0, "timeout waiting for frame");
            report;
        end
    end

    initial begin
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                if (!$value$plusargs("NONCE=%s", nonce))
                    if (!$value$plusargs("nonce=%s", nonce))
                        nonce = "missing-nonce";

        start_ok = 1'b0;
        stop_ok  = 1'b0;
        idle_ok  = 1'b0;
        rx       = 8'h00;

        // Reset, then let the line idle.
        rst = 1'b1;
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (4) @(negedge clk);

        fork
            begin : drive
                start = 1'b1;
                data  = FRAME_BYTE;
                @(negedge clk);
                start = 1'b0;
                data  = 8'h00;
            end
            begin : watch
                @(negedge tx);  // start-bit edge on the line
                fork
                    begin : intruder
                        // Falling edge in the middle of data bit 2: pulse start
                        // for one clock while the frame is in flight.
                        repeat (15) @(negedge clk);
                        start = 1'b1;
                        data  = INTRUDER_BYTE;
                        @(negedge clk);
                        start = 1'b0;
                        data  = 8'h00;
                    end
                    begin : sampler
                        // Middle of the start bit.
                        repeat (2) @(posedge clk);
                        @(negedge clk);
                        start_ok = (tx === 1'b0) && (busy === 1'b1);
                        // Middle of each data bit, LSB first.
                        for (i = 0; i < 8; i = i + 1) begin
                            repeat (CPB) @(negedge clk);
                            rx[i] = tx;
                        end
                        // Middle of the stop bit.
                        repeat (CPB) @(negedge clk);
                        stop_ok = (tx === 1'b1);
                        // After the frame: idle line, not busy, no second frame.
                        repeat (3) @(negedge clk);
                        idle_ok = (busy === 1'b0) && (tx === 1'b1);
                        for (i = 0; i < 3 * CPB; i = i + 1) begin
                            @(negedge clk);
                            if (busy !== 1'b0 || tx !== 1'b1)
                                idle_ok = 1'b0;
                        end
                    end
                join
            end
        join

        $display("frame byte on tx: %h, expected %h", rx, FRAME_BYTE);
        check(start_ok,           "start bit low with busy high");
        check(rx === FRAME_BYTE,  "frame byte unchanged by start while busy");
        check(stop_ok,            "stop bit high");
        check(idle_ok,            "idle after frame, ignored start sends nothing");
        report;
    end
endmodule
